export function evaluate({ inputs, time }) {
  const u = inputs.launchSpeed, g = inputs.gravity;
  const T = u / g, E = 2 * T, H = u * u / (2 * g);
  const t = Math.min(Math.max(time, 0), E);
  const yT = u * t - g * t * t / 2;
  const vT = u - g * t;
  const aT = -g;
  const rel = t >= T;
  const tau = rel ? t - T : 0;
  const yD = rel ? H - g * tau * tau / 2 : H;
  const vD = rel ? -g * tau : 0;
  const aD = rel ? -g : 0;
  const base = 330, sc = 120;
  const Y = (m) => base - m * sc;
  const xt = 205, xd = 515;
  const sT = t < 0.001 ? 'At launch' : (Math.abs(t - T) < 0.005 ? 'At the top' : (t < T ? 'Rising' : (t >= E - 0.001 ? 'At launch height' : 'Falling')));
  const sD = !rel ? 'Held in place' : (t >= E - 0.001 ? 'At launch height' : (t < T + 0.1 ? 'Just released' : 'Falling together'));
  const o = [];
  o.push(...sdk.panel({ id: 'lane.toss', x: 20, y: 40, w: 290, h: 360, title: 'Toss', state: sT, role: 'input' }));
  o.push(...sdk.panel({ id: 'lane.drop', x: 330, y: 40, w: 290, h: 360, title: 'Drop', state: sD, role: 'output' }));
  o.push(...sdk.groundMark('mark.toss', 60, base + 12, 50));
  o.push(...sdk.groundMark('mark.drop', 370, base + 12, 50));
  o.push(...sdk.gate('gate.drop', xd, Y(H) + 20, { open: rel, w: 30 }));
  o.push(sdk.circle('ball.toss', xt, Y(yT), 24, { role: 'input' }));
  o.push(sdk.circle('ball.drop', xd, Y(yD), 24, { role: 'output' }));
  o.push(...sdk.vector('vec.v.toss', { x: xt - 30, y: Y(yT) }, { value: vT, direction: 'up' }, { scale: 8, label: 'v', role: 'observed' }));
  o.push(...sdk.vector('vec.a.toss', { x: xt + 30, y: Y(yT) }, { value: aT, direction: 'up' }, { scale: 3.5, label: 'a', role: 'warning' }));
  o.push(...sdk.vector('vec.v.drop', { x: xd - 30, y: Y(yD) }, { value: vD, direction: 'up' }, { scale: 8, label: 'v', role: 'observed' }));
  o.push(...sdk.vector('vec.a.drop', { x: xd + 30, y: Y(yD) }, { value: aD, direction: 'up' }, { scale: 3.5, label: 'a', role: 'warning' }));
  o.push(...sdk.callout(28, 240, ['v = ' + sdk.format(vT, 2) + ' m/s', 'a = ' + sdk.format(aT, 1) + ' m/s²'], { id: 'callout.toss' }));
  o.push(...sdk.callout(338, 240, ['v = ' + sdk.format(vD, 2) + ' m/s', 'a = ' + sdk.format(aD, 1) + ' m/s²'], { id: 'callout.drop' }));
  return {
    frame: { width: 640, height: 420, objects: o, readouts: [
      { id: 'tossedVelocity', value: vT }, { id: 'tossedAcceleration', value: aT },
      { id: 'dropVelocity', value: vD }, { id: 'dropAcceleration', value: aD }] },
    quantities: { launchSpeed: u, gravity: g, apexTime: T, apexHeight: H, tossedVelocity: vT, tossedAcceleration: aT, tossedHeight: yT, dropVelocity: vD, dropAcceleration: aD, dropHeight: yD }
  };
}
